};

function fmt(msg) {
    if (msg.payload.command == "click" || msg.payload.command == "doubleclick" || msg.payload.command == "tripleclick") {
        return "" + msg.payload.command + " of button " + msg.payload.button + (msg.selection ? " (mode " + msg.selection + ")" : "");
    }
    else if (msg.payload.command == "up" || msg.payload.command == "down") {
        return "" + msg.payload.command + " of step size " + msg.payload.step_size + (msg.selection ? " (mode " + msg.selection + ")" : "");
    }
    return JSON.stringify(msg);
}

function status(msg, buffering) {
    node.status({ text: msg, fill: "blue", shape: buffering ? "ring" : "dot"});
}

if (current.msg.flush) {
    if (last !== undefined && last !== null) {
        context.set("last_active", null);
        status("flushing  " + fmt(last.msg), false);
        return [[last.msg], null];
    }
}
else if (current.msg.payload.command == "click") {
    if (last === undefined || last === null) {
        context.set("last_active", current);
        status("buffering " + fmt(current.msg), true);
        return [null, { flush: true }];
    } else {
        if (
            current.msg.payload.button == last.msg.payload.button
        ) {
            if (
                last.msg.payload.command == "click"
            ) {
                // Instead of queueing the current message,
                // update the last message.
                last.msg.payload.command = "doubleclick";
                status("rebuffering " + fmt(last.msg), true);
                return [null, { flush: true }];
            }
            else if (
                last.msg.payload.command == "doubleclick"
            ) {
                last.msg.payload.command = "tripleclick";
                context.set("last_active", null);
                status("flushing " + fmt(last.msg), false);
                return [[last.msg], null];
            }
            else {
                // This is an error
                node.error({msg:"Cannot be", current: current, last: last})
            }
        } else { /* buttons don't match */
            context.set("last_active", current);
            status("flushing " + fmt(last.msg) + " and buffering " + fmt(current.msg), true);
            return [[last.msg], { flush: true }];
        }
    }
}
else {
    if (last === undefined || last === null) {
        status("relaying " + fmt(current.msg), false);
        return [current.msg];
    }
    else {
        context.set("last_active", null);
        status("relaying previous " + fmt(last.msg) + " and current " + fmt(current.msg), false);
        return [[last.msg, current.msg], null];
    }
}

