var now = Date.now();
var last_brightness_pct = flow.get("last_brightness_pct");
var last_brightness_pct_time = flow.get("last_brightness_pct_time");

if (last_brightness_pct_time !== undefined && now - last_brightness_pct_time < 5000) {
    var brightness_pct = last_brightness_pct;
} else {
    var brightness_pct = msg.data.attributes.brightness;
    if (brightness_pct === undefined) {
        node.status({ fill: "yellow", text: "receiver off / cannot get brightness: " + new Date().toLocaleString() });
        return;
    }
}
var dim_direction = msg.dim_direction;
brightness_pct = brightness_pct + dim_direction;
brightness_pct = Math.min(Math.max(0, brightness_pct), 255);
msg.payload = brightness_pct;
flow.set("last_brightness_pct", brightness_pct);
flow.set("last_brightness_pct_time", now);
node.status({fill: "green", text: brightness_pct.toFixed(3) + ": " + new Date().toLocaleString()})
return msg;
